type UserPreferences = {
  theme?: string
  language?: string
  notifications?: boolean
  [key: string]: unknown
}

// Fetches user-specific preferences that change on each request.
// `cache: 'no-store'` guarantees the resource is fetched from the remote
// server on every request, so the route is not statically prerendered with
// stale build-time data.
async function getUserPreferences(): Promise<UserPreferences> {
  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })
    return (await res.json()) as UserPreferences
  } catch {
    // Return mock data when the remote API is unavailable (e.g. at build time)
    return {
      theme: 'system',
      language: 'en',
      notifications: true,
    }
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()

  return (
    <div>
      <h2>User Dashboard</h2>
      <ul>
        <li>Theme: {String(preferences.theme)}</li>
        <li>Language: {String(preferences.language)}</li>
        <li>
          Notifications: {preferences.notifications ? 'Enabled' : 'Disabled'}
        </li>
      </ul>
    </div>
  )
}
